// W tym kursie uzywamy H2 - lekkiej, czysto-javowej, relacyjnej
// bazy danych, dzialajacej w trybie IN-MEMORY, WEWNATRZ TEJ SAMEJ
// JVM co aplikacja - bez osobnego serwera, bez instalacji.
// UWAGA: to NIE JEST typowy scenariusz produkcyjny - w realnych
// aplikacjach baza to niemal zawsze ODREBNY serwer.

try (Connection conn = DriverManager.getConnection(
        "jdbc:h2:mem:lesson01;DB_CLOSE_DELAY=-1");
     Statement stmt = conn.createStatement()) {

    stmt.execute("CREATE TABLE users (id INT PRIMARY KEY, name VARCHAR(100), email VARCHAR(100))");
    stmt.execute("INSERT INTO users VALUES (1, 'Jan Kowalski', 'jan@example.com')");
    stmt.execute("INSERT INTO users VALUES (2, 'Anna Nowak', 'anna@example.com')");

    ResultSet rs = stmt.executeQuery("SELECT * FROM users");
    while (rs.next()) {
        System.out.println(rs.getInt("id") + " - " + rs.getString("name"));
    }
}

// URL "jdbc:h2:mem:lesson01;DB_CLOSE_DELAY=-1":
// "jdbc:h2:mem:" -> tryb pamieciowy H2
// "lesson01" -> nazwa instancji bazy
// "DB_CLOSE_DELAY=-1" -> nie usuwaj bazy po zamknieciu 1. polaczenia
